 function renderDiscoveries(force=false){const now=new Date(),day=now.getFullYear()+'-'+(now.getMonth()+1)+'-'+now.getDate();if(day!==discoveryDay){discoveryDay=day;discoveryNonce=0;}const groups=new Map();for(const song of (discoveryCandidates.length?discoveryCandidates:songs).filter(s=>!s.removedAt&&!s.duplicateOf)){const key=albumKey(song);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(song);}let pool=[...groups.values()];const illustrated=pool.filter(g=>g.some(s=>s.cover));if(illustrated.length>=4)pool=illustrated;const signature=day+'|'+discoveryNonce+'|'+pool.map(g=>g.map(s=>s.id).sort().join(',')).sort().join(';');if(!force&&signature===discoverySignature)return;discoverySignature=signature;const shelf=el('discovery-shelf');shelf.replaceChildren();for(const group of discoverySelection(pool,day+'|'+discoveryNonce)){const song=group.find(s=>s.cover)||group[0],button=make('button',undefined,'discovery-album discovery-item discovery-record');button.setAttribute('aria-label','Open '+albumLabel(song)+' by '+albumArtist(song));button.title=albumLabel(song)+' · '+albumArtist(song);button.append(artwork(song),make('span',albumLabel(song),'discovery-title'));const image=button.querySelector('img');if(image){image.loading='eager';image.decoding='async';image.fetchPriority='high';}button.onclick=async()=>{button.disabled=true;try{if(!catalogLoaded)await load();const full=songs.filter(s=>!s.removedAt&&!s.duplicateOf&&albumKey(s)===albumKey(group[0]));if(full.length)openAlbum(full);else el('discovery-status').textContent='This album is no longer available.';}catch(error){el('discovery-status').textContent=error.message;}finally{button.disabled=false;}};shelf.append(button);}if(!pool.length)shelf.append(make('p','Add some music to discover here.'));shelf.scrollLeft=0;el('discover-surprise').disabled=pool.length<2;requestAnimationFrame(discoveryArrows);}
 function discoveryArrows(){const shelf=el('discovery-shelf');el('discover-previous').disabled=shelf.scrollLeft<=1;el('discover-next').disabled=shelf.scrollLeft+shelf.clientWidth>=shelf.scrollWidth-2;}
 el('discover-surprise').onclick=()=>{discoveryNonce++;renderDiscoveries(true);el('discovery-status').textContent='A fresh selection of albums.';};
