 async function refreshArtwork(){if(artPollBusy||!window.MAHA_CAN_MANAGE)return;artPollBusy=true;try{const data=await post('/art/status',{});artRunning=!!(data.counts.queued||data.counts.running||data.counts.waiting);el('art-status').textContent=Object.entries(data.counts).map(([state,count])=>count+' '+state).join(' · ')||'No artwork lookups yet.';const list=el('art-jobs');list.replaceChildren();for(const job of data.jobs){const item=make('section',undefined,'art-job');item.append(make('h3',job.album),make('p',job.artist+' · '+job.message));if(job.state==='waiting'&&job.nextAttempt)item.append(make('small','Next retry: '+new Date(job.nextAttempt*1000).toLocaleString()));if(['fallback','error','waiting'].includes(job.state)){const retry=make('button','Retry lookup','text-btn');retry.onclick=async()=>{const group=artGroups().find(g=>albumLabel(g[0])===job.album&&albumArtist(g[0])===job.artist);if(!group){el('art-status').textContent='This album now has artwork or is no longer available.';return;}retry.disabled=true;try{await queueArtwork(group);await refreshArtwork();}catch(error){el('art-status').textContent=error.message;}finally{retry.disabled=false;}};item.append(retry);}if(job.state==='review')for(const [index,candidate] of job.candidates.entries()){const button=make('button',undefined,'art-candidate'),img=make('img');img.src=candidate.url;img.alt=candidate.title+' cover';button.append(img,make('span',candidate.title+' — '+candidate.artist+' '+candidate.year),make('span','Use this cover'));button.onclick=async()=>{button.disabled=true;try{await post('/art/apply',{job:job.id,candidate:index});await load();await refreshArtwork();}catch(error){el('art-status').textContent=error.message;}finally{button.disabled=false;}};item.append(button);}list.append(item);}}catch(error){el('art-status').textContent=error.message;}finally{artPollBusy=false;}}
 el('manage-art').onclick=()=>{if(window.MAHA_SESSION?.user?.role!=='super')return;el('manage-art').closest('details').open=false;el('art-manager').showModal();refreshArtwork();};el('art-close').onclick=()=>el('art-manager').close();el('art-manager').addEventListener('close',()=>{if(artBusy)el('music-status').textContent='Artwork queueing continues while this page stays open. Reopen Album artwork to see progress.';});
