 function bindSelection(node,group){const ids=group.map(s=>s.id);if(!ids.length)return;node.dataset.selectionIds=JSON.stringify(ids);node.classList.add('music-selectable');node.title='Ctrl-click to select or deselect';if(node.tagName!=='BUTTON'){node.tabIndex=0;node.setAttribute('aria-label',group.length===1?group[0].title:'Select recordings');}const toggle=event=>{event.preventDefault();event.stopImmediatePropagation();if(bulkBusy)return;const deselect=ids.every(id=>selectedIds.has(id));if(!deselect&&new Set([...selectedIds,...ids]).size>1000){el('music-status').textContent='Select up to 1,000 recordings at a time.';return;}for(const id of ids)deselect?selectedIds.delete(id):selectedIds.add(id);renderBulk();};node.addEventListener('click',event=>{if(event.ctrlKey||event.metaKey)toggle(event);},true);node.addEventListener('keydown',event=>{if(event.target===node&&event.code==='Space')toggle(event);});}
 function renderBulk(){for(const node of document.querySelectorAll('[data-selection-ids]')){const ids=JSON.parse(node.dataset.selectionIds),full=ids.every(id=>selectedIds.has(id)),partial=!full&&ids.some(id=>selectedIds.has(id));node.classList.toggle('music-selected',full);node.classList.toggle('music-partial',partial);node.setAttribute('aria-description',full?'Selected':partial?'Partly selected':'Not selected');}el('bulk-tools').hidden=!selectedIds.size;const selected=songs.filter(s=>selectedIds.has(s.id));el('bulk-count').textContent=selected.length+' selected · '+fileSize(selected.reduce((n,s)=>n+(s.bytes||0),0));for(const action of ['tag','untag','remove','delete'])el('bulk-'+action).disabled=bulkBusy||!selected.length||(['tag','untag','remove'].includes(action)&&!selected.every(s=>s.canEdit));el('bulk-all').disabled=bulkBusy;el('bulk-clear').disabled=bulkBusy||!selected.length;el('bulk-delete').hidden=!selected.length||!selected.every(s=>s.canDelete);}
 el('bulk-all').onclick=()=>{const ids=filtered.map(s=>s.id);if(new Set([...selectedIds,...ids]).size>1000){el('music-status').textContent='Narrow your filters to select up to 1,000 recordings.';return;}for(const id of ids)selectedIds.add(id);render();};
