 function confirmBulkDelete(preview){return new Promise(resolve=>{const previous=document.activeElement,d=make('dialog',undefined,'personal-dialog bulk-delete-dialog'),heading=make('h2','Permanently delete recordings?'),summary=make('p'),warning=make('p','This deletes the managed audio files and their artwork. It cannot be undone. Separate source-drive originals are kept.'),form=make('form'),label=make('label'),phrase=make('code',preview.phrase),input=make('input'),actions=make('div',undefined,'bulk-delete-actions'),cancel=make('button','Cancel'),confirm=make('button','Permanently delete '+preview.count+' files','action');heading.id='bulk-delete-heading';warning.id='bulk-delete-warning';d.setAttribute('aria-labelledby',heading.id);d.setAttribute('aria-describedby',warning.id);summary.append(make('strong',preview.count+' recordings · '+fileSize(preview.bytes)));label.append(make('span','Type the following phrase to confirm: '),phrase,input);input.type='text';input.autocomplete='off';input.spellcheck=false;input.setAttribute('aria-label','Deletion confirmation phrase');input.setAttribute('aria-describedby','bulk-delete-warning');confirm.type='submit';confirm.disabled=true;cancel.type='button';cancel.onclick=()=>d.close();input.addEventListener('input',()=>{confirm.disabled=input.value!==preview.phrase;});actions.append(cancel,confirm);form.append(label,actions);form.addEventListener('submit',event=>{event.preventDefault();if(input.value===preview.phrase)d.close('confirmed');});const details=make('details'),list=make('ul',undefined,'bulk-delete-files');details.append(make('summary','Review '+preview.count+' recordings'));for(const song of preview.recordings)list.append(make('li',song.title+' — '+song.artist));details.append(list);if(preview.count>preview.recordings.length)details.append(make('small','Showing '+preview.recordings.length+' of '+preview.count+' selected recordings.'));d.append(heading,summary,warning,form,details);d.addEventListener('click',event=>{if(event.target!==d)return;const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();});d.addEventListener('close',()=>{const result=d.returnValue==='confirmed'?input.value:null;d.remove();if(previous?.isConnected)previous.focus();resolve(result);},{once:true});document.body.append(d);d.showModal();input.focus();});}
 async function bulkAction(action){if(bulkBusy||!selectedIds.size)return;const ids=[...selectedIds];let data={action,ids};bulkBusy=true;render();try{if(action==='tag'||action==='untag'){data.tags=el('bulk-tags').value.split(',').map(t=>t.trim()).filter(Boolean);if(!data.tags.length)throw Error('Enter at least one tag.');}if(action==='remove'&&!window.confirm('Remove '+ids.length+' recordings from the library? Managed audio files will be kept.'))return;if(action==='delete'){const preview=await post('/bulk-preview',{ids});const confirmation=await confirmBulkDelete(preview);if(confirmation===null)return;data={action,token:preview.token,confirmation};}const result=await post('/bulk',data);for(const id of result.completed)selectedIds.delete(id);if(action==='remove'||action==='delete'){const done=new Set(result.completed);queue=queue.filter(s=>!done.has(s.id));if(done.has(current?.id)){el('audio').pause();el('audio').removeAttribute('src');el('audio').load();current=null;el('player').hidden=true;}syncPlayer();}await load();el('music-status').textContent=result.completed.length+' recordings updated.'+(action==='delete'?' Freed '+fileSize(result.bytesRemoved)+'. Separate source originals kept.':'')+(result.errors.length?' '+result.errors.length+' failed and remain selected. Retry or refresh.':'');}catch(error){el('music-status').textContent=error.message;}finally{bulkBusy=false;render();}}
