 state(){const a=el('audio'),i=queue.findIndex(s=>s.id===current?.id);return {song:current?{id:current.id,title:current.title,artist:current.artist,album:albumLabel(current),cover:current.cover||songs.find(song=>albumKey(song)===albumKey(current)&&song.cover)?.cover,favorite:!!window.MAHA_PERSONAL?.has(songFavorite(current))}:null,playing:!a.paused,time:a.currentTime,duration:Number.isFinite(a.duration)?a.duration:(current?.duration||0),shuffle,repeat,count:queue.length,previous:i>0||repeat,next:i<queue.length-1||repeat||(shuffle&&queue.length>1),error:a.error?'This recording could not be played. Try another song.':''};},
